// Gachon University, Global Campus (가천대학교 글로벌캠퍼스, 경기 성남시 수정구 복정동). Data is generated by scripts/campuses/gachon/build-package.mjs
// from the pilot (pilot/gachon-seongnam): every model of active-models.json (가천관·비전타워·중앙도서관·AI관 detailed, 대운동장 스탠드 custom,
// the rest generic), all destructible (no hospital, religious or hanok heritage building on this campus - rule 10.1: the protected list
// is empty), a baked ground drawn with the pilot's ground shader (the SKKU port src/campuses/skku/ground-look.js; the pilot's
// final-materials.js is the same shader as uos's / dankook's), the preview's own retaining walls / stairs / ribbons / skirts and planting
// (same trees), landscape/*.gltf (무한대상, pitches) and the non-destructible context fading into the haze. Local only until the user
// approves (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, GACHON_PLACEMENTS, GACHON_BUILDING_BASE, GACHON_HEIGHT_GRIDS, GACHON_HEIGHT_RANGE_M, GACHON_ENV_IDS, GACHON_ENV_MANIFEST_IDS, GACHON_LOOK, GACHON_ZONES, GACHON_DISPLAY, GACHON_PROVENANCE } from './data.js';
import { GACHON_FOOTPRINTS } from './footprints.js';
import { GACHON_PROTECTED } from './protected.js';
import { createSkkuGroundLook } from '../skku/ground-look.js';

const MODEL_IDS = Object.freeze(GACHON_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/gachon/${file}`, import.meta.url).href;
const HAZE = GACHON_DISPLAY.haze, FADE = GACHON_DISPLAY.fade;

export const GACHON = Object.freeze({
  id: 'gachon',
  meta: Object.freeze({ school: '가천대학교', campus: '글로벌캠퍼스', short: '가천대', modelNoun: '가천대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: GACHON_PLACEMENTS,
  approvedCount: GACHON_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['gachonHall', 'visionTower', 'centralLibrary', 'aiHall'].filter(id => MODEL_IDS.includes(id))),
  startBuildingId: 'gachonHall',
  // Start: from over the 비전타워 / 법과대학 side (west-southwest) looking east-northeast across the central plaza: 무한대상 (the origin,
  // E 0 / N 0) in the middle, 가천관 (E 53 / N -17) behind it, AI도서관 / 바이오나노대학 / 한의과대학 / 예술·체육대학2 around the plaza.
  // Box in world units (metres x 0.5, z = -N): E -50..80 m, N -44..44 m, 0..24 m high; azimuth -1.3 = camera west, a little south.
  // Projected in Node with src/camera.js (scripts/campuses/gachon/start-frame-check.mjs, W1 2026-10-22): camera at E -179 / N -54 m, 105 m
  // up (1280x800; E -391 / N -113, 207 m up at 390x844); 무한대상 at screen (619, 477) / (185, 462), 가천관 roof at y 160 / 300 (inside
  // the HUD-free band 96..712 / 96..756); campus buildings' share of the band 0.38 / 0.36, 9 / 10 of 22 buildings on screen.
  view: Object.freeze({ startFrame: Object.freeze({ min: Object.freeze([-25, -1, -22]), max: Object.freeze([40, 12, 22]), azimuth: -1.3 }) }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: GACHON_ENV_MANIFEST_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: GACHON_HEIGHT_GRIDS, buildingBase: GACHON_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30, building-filled + floor-link / photo level evidence, pilot/gachon-seongnam); not a survey' }),
  environment: Object.freeze({ provenance: GACHON_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the landscape models estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: GACHON_ENV_IDS, castShadow: Object.freeze([]), materialHook: createSkkuGroundLook(GACHON_LOOK, GACHON_ZONES),
      // context.json display fade (preview.js FADE): campus clear to r0, the backdrop melts into the haze by r1
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, ...(FADE.linearShare ? { linear: FADE.linearShare } : {}), colour: HAZE }), playMargin_m: 30,
      source: 'pilot/gachon-seongnam preview ground + planting + landscape + context, baked' }),
  }),
  // Protected: none (every model destructible). Kept so a later decision only needs a rebuild; the manifest exists only when the list
  // is not empty (src/main.js loads protected models only when models.length > 0).
  protected: Object.freeze({
    ...(GACHON_PROTECTED.length ? { manifestURL: asset('protected/manifest.json') } : {}),
    models: GACHON_PROTECTED,
  }),
  // Hazard tape around every destructible building (src/engine/hazard-tape.js): none on the context.
  hazardTape: Object.freeze({ footprints: GACHON_FOOTPRINTS }),
  scene: Object.freeze({
    // preview.js: hemisphere (#fff, #7d8a78, 1.35), sun #fff4e2 3.1 from (-180, 340, 280) towards (140, 20, -160) -> that direction, halved
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 700, far: 2400 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-160, 160, 220]), shadowSpan: 260 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: GACHON_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default GACHON;
